sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /^\s*import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my $block = defined $1 ? $1 : qq{"$2"};
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $path =~ s{^\Q$module\E/}{};
            $alias //= ($path =~ m{/([^/]+)$})[0];
            $imports{$alias} = $path;
        }
    }
    return %imports;
