#!/usr/bin/perl
use strict;
use warnings;

my $root = '/bench/repo';
my $module = 'github.com/usememos/memos';

my @gofiles = `find '$root' -name '*.go' -type f`;
chomp @gofiles;

my %defs;
my %files;

sub rel_pkgpath {
    my ($f) = @_;
    return undef unless $f =~ m{/internal/};
    (my $pp = $f) =~ s{^\Q$root\E/}{};
    $pp =~ s{/[^/]+$}{};
    return $pp;
}

sub read_file {
    my ($f) = @_;
