    local $/; my $c = <$fh>; close $fh;
    return $c;
}

sub strip_comments {
    my ($c) = @_;
    $c =~ s{//[^\n]*}{}g;
    $c =~ s{/\*.*?\*/}{}gs;
    return $c;
}

sub parse_imports {
